function validate(input) {
  const [start, end, step] = input;
  const day = (text) => {
    if (typeof text !== 'string' || !/^\d{4}-\d{2}-\d{2}$/.test(text) || text < '1000') return null;
    const time = Date.parse(`${text}T00:00:00Z`);
    if (Number.isNaN(time) || new Date(time).toISOString().slice(0, 10) !== text) return null;
    return time / 86400000;
  };
  const first = day(start), last = day(end);
  if (first === null) return 'start must be a real date written as YYYY-MM-DD, from year 1000.';
  if (last === null) return 'end must be a real date written as YYYY-MM-DD, from year 1000.';
  if (last < first) return 'end must not be before start.';
  if (last - first > 1500) return 'end may be at most 1500 days after start.';
  if (!Number.isInteger(step) || step < 1 || step > 1000) return 'step must be an integer from 1 to 1000.';
  return null;
}

