function adapt(input, solve, kit) {
  const [start, end, step] = input;
  const gen = solve(start, end, step);
  if (!gen || typeof gen.next !== 'function') throw new Error('dateRangeGenerator must return a generator object.');
  kit.trace(`dateRangeGenerator("${start}", "${end}", ${step}) creates the generator`);
  const dates = [];
  for (;;) {
    const result = gen.next();
    if (!result || typeof result !== 'object') throw new Error('next() must return an object { value, done }.');
    if (result.done) {
      kit.trace('gen.next() reports that the generator is done');
      break;
    }
    if (typeof result.value !== 'string') throw new Error('Each yielded value must be a date string such as "2023-04-01".');
    kit.trace(`gen.next() yields "${result.value}"`);
    dates.push(result.value);
    if (dates.length > 1501) throw new Error('The generator yielded more than 1,501 dates; it should stop once it passes end.');
  }
  return dates;
}

