function* dateRangeGenerator(start, end, step) {
  // Walk the calendar one day at a time by hand, without Date, and yield every step-th day.
  const leap = (year) => (year % 4 === 0 && year % 100 !== 0) || year % 400 === 0;
  const monthLength = (year, month) => [31, leap(year) ? 29 : 28, 31, 30, 31, 30, 31, 31, 30, 31, 30, 31][month - 1];
  const pad = (value, width) => String(value).padStart(width, '0');
  let [year, month, day] = start.split('-').map(Number);
  for (let offset = 0; ; offset++) {
    const text = `${pad(year, 4)}-${pad(month, 2)}-${pad(day, 2)}`;
    if (text > end) return;
    if (offset % step === 0) yield text;
    day++;
    if (day > monthLength(year, month)) {
      day = 1;
      month++;
      if (month > 12) {
        month = 1;
        year++;
      }
    }
  }
}

