function generate(rand, size) {
  const small = size === 'small';
  const DAY = 86400000;
  // Start between 1899-01-01 and 2401-12-31 so leap rules for 1900, 2000, 2100 and 2400 come up.
  const low = Date.UTC(1899, 0, 1) / DAY, high = Date.UTC(2401, 11, 31) / DAY;
  let first = low + Math.floor(rand() * (high - low + 1));
  if (rand() < 0.3) {
    // Start near the end of February in a century year or a leap year.
    const year = [1900, 2000, 2024, 2100, 2023, 2400][Math.floor(rand() * 6)];
    first = Date.UTC(year, 1, 20 + Math.floor(rand() * 9)) / DAY;
  }
  const span = small ? Math.floor(rand() * 41) : 1000 + Math.floor(rand() * 501);
  const step = small ? 1 + Math.floor(rand() * 12) : rand() < 0.5 ? 1 + Math.floor(rand() * 5) : 1 + Math.floor(rand() * 1000);
  const text = (days) => new Date(days * DAY).toISOString().slice(0, 10);
  return [text(first), text(first + span), step];
}
